output:
body {
    background-color: #f8f9fa;
}

.navbar {
    margin-bottom: 20px;
}

.jumbotron {
    background-image: url('../images/jumbotron.jpg');
    background-size: cover;
    background-position: center;
    color: white;
    position: relative;
    overflow: hidden;
}

.jumbotron .overlay {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(0, 0, 0, 0.5); /* Semi-transparent overlay */
    z-index: 1;
}

.jumbotron .content {
    position: relative;
    z-index: 2;
}

.card-header {
    background-color: #007bff;
    color: white;
}

.footer {
    background-color: #343a40;
    color: white;
    padding: 10px 0;
}

.footer p {
    margin: 0;
}
